SELECT C.*,D.F_COMMENT FROM( WITH EQP_FILTER_DATA AS ( SELECT DISTINCT A.SHIFT_DATE , B.EQP_ID , A.PORT_ID FROM ( SELECT SHIFT_DATE , KEY1 AS EQP_ID , KEY2 AS PORT_ID , KEY3 AS FAB , KEY4 AS MODULE FROM A1_MFG.CRITICLE_COMMENT_SUMMARY_HS S WHERE FUNCTION_NAME = 'LP Monitor Filter' )A JOIN ( SELECT DISTINCT #{fab} AS FAB , EQP_ID FROM PWEB.EQP_ID_USE_STD@A1PDW WHERE LENGTH(EQP_ID) = 5 UNION ALL SELECT DISTINCT 'N1A3' AS FAB , EQP_ID FROM PWEB.EQP_ID_USE_STD@A3PDW WHERE LENGTH(EQP_ID) = 6 ) B ON A.FAB = B.FAB AND INSTR(B.EQP_ID, A.EQP_ID) > 0 ) SELECT A.FAB_PHASE , A.SHIFT_DATE , A.MFG_MODULE MODULE , A.EQP_G , A.EQP_ID , A.PORT_ID , A.MCOPEMODE_ID OPE_MODE , A.CLAIM_TIME , ROUND((A.UPDATE_TIME-A.CLAIM_TIME )*24,2) AS DUR , A.UPDATE_TIME FROM A1_MFG.PH_EQP_PORT A WHERE A.FAB_PHASE =#{fab} AND A.MFG_MODULE =#{module}
AND A.EQP_G = #{eqpg}
AND A.SHIFT_DATE = #{shiftDate}
AND A.SHIFT_MONTH = #{shiftDate}
AND NOT EXISTS ( SELECT 1 FROM EQP_FILTER_DATA C WHERE A.SHIFT_DATE = C.SHIFT_DATE AND A.EQP_ID = C.EQP_ID AND A.PORT_ID = C.PORT_ID ) UNION ALL SELECT A.FAB_PHASE , A.SHIFT_DATE , A.MFG_MODULE , A.EQP_G , A.EQP_ID , A.PORT_ID , A.MCOPEMODE_ID , A.CLAIM_TIME , ROUND((SYSDATE-A.CLAIM_TIME )*24,2) AS DUR , SYSDATE AS UPDATE_TIME FROM A1_MFG.V_PR_EQP_PORT A WHERE A.FAB_PHASE =#{fab} AND A.MFG_MODULE =#{module}
AND A.EQP_G = #{eqpg}
AND A.SHIFT_DATE = #{shiftDate}
AND A.SHIFT_MONTH = #{shiftDate}
)C LEFT JOIN ( SELECT KEY1 EQP_ID,KEY2 PORT_ID,TO_DATE(KEY3,'YYYY-MM-DD HH24:MI:SS') CLAIM_TIME,F_COMMENT FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'lpHealthDetailComment' )D ON C.EQP_ID = D.EQP_ID AND C.PORT_ID = D.PORT_ID AND C.CLAIM_TIME = D.CLAIM_TIME

SELECT EQP_ID label,EQP_ID value FROM( SELECT A.EQP_G,A.EQP_ID, CASE WHEN B.MODULE IS NOT NULL THEN B.MODULE WHEN A.MODULE IN('FA', 'INT','Measurement') THEN 'METRO' ELSE A.MODULE END MODULE FROM( SELECT DISTINCT EQP_G,EQP_ID,MODULE FROM PWEB.EQP_ID_USE_STD WHERE LENGTH(EQP_ID)=5 AND ACTIVE_FLAG = 'Y' AND #{fab,jdbcType=VARCHAR} IN ('N1','N1A1') )A LEFT JOIN ( SELECT KEY1 MODULE,KEY2 EQP_G FROM A1_MFG.CRITICLE_COMMENT_SUMMARY@TO_A3MFG B WHERE FUNCTION_NAME ='EQPG MODULE' )B ON A.EQP_G = B.EQP_G UNION SELECT A.EQP_G,A.EQP_ID, CASE WHEN B.MODULE IS NOT NULL THEN B.MODULE WHEN A.MODULE IN('FA', 'INT','Measurement') THEN 'METRO' ELSE A.MODULE END MODULE FROM( SELECT DISTINCT EQP_G,EQP_ID,MODULE FROM PWEB.EQP_ID_USE_STD_A3 WHERE LENGTH(EQP_ID)=6 AND ACTIVE_FLAG = 'Y' AND #{fab,jdbcType=VARCHAR} IN ('N1','N1A3') )A LEFT JOIN ( SELECT KEY1 MODULE,KEY2 EQP_G FROM A1_MFG.CRITICLE_COMMENT_SUMMARY@TO_A3MFG B WHERE FUNCTION_NAME ='EQPG MODULE' )B ON A.EQP_G = B.EQP_G ) WHERE 1=1
AND MODULE = #{module,jdbcType=VARCHAR}
AND EQP_G = #{eqpg,jdbcType=VARCHAR}

        SELECT A.FAB_PHASE
        , A.SHIFT_DATE
        , A.MFG_MODULE
        , A.EQP_G
        , A.EQP_ID
        , A.TTL_MOVE
        , A.DYB_MOVE
        ,CASE WHEN A.TTL_MOVE > 0 THEN ROUND(A.DYB_MOVE/A.TTL_MOVE*100,2) ELSE 0 END AS DYB_RATIO
        FROM A1_MFG.PH_MOVE_HISTORY_SUMMARY A
        WHERE A.FAB_PHASE =#{fab}
        AND A.MFG_MODULE =#{module}
        AND A.EQP_G =#{eqpg}



                    AND A.SHIFT_DATE = #{shiftDate}


                    AND A.SHIFT_MONTH = #{shiftDate}



ORDER BY A.DYB_MOVE  DESC

