SELECT ROUND(MAX(T3.SR)*100,1) AS OPD_SR,NVL(T.EQP_G_NEW,T.EQP_G) AS EQP_G,T.SHIFT_DATE,SUM(T.TOTAL_MOVE) AS MOVE, CASE WHEN SUM(TOTAL_MOVE) > 0 THEN ROUND(SUM(MAIN_MOVE)/ SUM(TOTAL_MOVE),3)*100 ELSE NULL END AS ACT_SR, CASE WHEN SUM(WIP) > 0 THEN ROUND(SUM(PSTD_SR * WIP) / SUM(WIP),3)*100 ELSE NULL END AS PSTD_SR FROM A3MFGYW1.T_MFG_SR_KPI T INNER JOIN A3MFGYW1. PRODG_INFO T2 ON T.PRODG1=T2.PRODG1 AND T.FAB = T2.FAB LEFT JOIN A3MFGYW1.T_OPD_SR T3 ON T.EQP_G=T3.EQP_G WHERE T.SHIFT_DATE=TO_CHAR(SYSDATE-8/24-1,'YYYYMMDD')
AND T.FAB= #{location,jdbcType=VARCHAR}
AND T.PRODUCT_STATUS IN
#{item,jdbcType=VARCHAR}
AND T2.TECH = #{tech,jdbcType=VARCHAR}
GROUP BY NVL(T.EQP_G_NEW,T.EQP_G),T.SHIFT_DATE ORDER BY NVL(SUM(T.TOTAL_MOVE),0) DESC

WITH SR_DATA AS ( SELECT TECH,QA_ADI,QA_AEI,QA_AEI_CMP,QA_AFM,QB_BUBBLE,QB_BUBBLE_STK,QC_THK,QC_THK_SI,QC_TRIM,QG_DEFECT,QP_DEFECT,QS_SEM,QW_SEM,QX_OVERLY,QY_D_PC,QZ_DEFECT FROM ( SELECT T2.TECH, NVL(T.EQP_G_NEW, T.EQP_G) AS EQP_G, CASE WHEN SUM(WIP) OVER (PARTITION BY T2.TECH, NVL(T.EQP_G_NEW, T.EQP_G)) > 0 THEN ROUND(SUM(PSTD_SR * WIP) OVER (PARTITION BY T2.TECH, NVL(T.EQP_G_NEW, T.EQP_G)) / SUM(WIP) OVER (PARTITION BY T2.TECH, NVL(T.EQP_G_NEW, T.EQP_G)), 3) ELSE NULL END AS PSTD_SR FROM A3MFGYW1.T_MFG_SR_KPI T INNER JOIN A3MFGYW1.PRODG_INFO T2 ON T.PRODG1 = T2.PRODG1 AND T.FAB = T2.FAB WHERE T.SHIFT_DATE = TO_CHAR(SYSDATE-8/24-1, 'YYYYMMDD')
AND T.FAB= #{location,jdbcType=VARCHAR}
AND T.PRODUCT_STATUS IN
#{item,jdbcType=VARCHAR}
) PIVOT ( MAX(PSTD_SR) FOR EQP_G IN ( 'QA_ADI' AS QA_ADI, 'QA_AEI' AS QA_AEI, 'QA_AEI_CMP' AS QA_AEI_CMP, 'QA_AFM' AS QA_AFM, 'QB_Bubble' AS QB_Bubble, 'QB_Bubble_STK' AS QB_Bubble_STK, 'QC_THK' AS QC_THK, 'QC_THK_Si' AS QC_THK_Si, 'QC_Trim' AS QC_Trim, 'QG_Defect' AS QG_Defect, 'QP_Defect' AS QP_Defect, 'QS_SEM' AS QS_SEM, 'QW_SEM' AS QW_SEM, 'QX_Overly' AS QX_Overly, 'QY_D.PC' AS QY_D_PC, 'QZ_Defect' AS QZ_Defect ) ) ORDER BY TECH ), SR_TEMP AS( SELECT A.*,B.WIP FROM SR_DATA A LEFT JOIN ( SELECT T2.TECH,SUM(T.WAFER_QTY) AS WIP FROM A3MFGYW1.LOT_PRIORITY_HISTORY T INNER JOIN A3MFGYW1.PRODG_INFO T2 ON T.PRODG1=T2.PRODG1 AND T.FAB=T2.FAB INNER JOIN ( SELECT DISTINCT T.PRODG1,T.FAB,T.SHIFT_DATE FROM A3MFGYW1.T_MFG_SR_KPI T ) T3 ON T.PRODG1 = T3.PRODG1 AND T.FAB = T3.FAB AND T.SHIFT_DATE=T3.SHIFT_DATE WHERE T.SHIFT_HOUR = '01' and t.NENG_FLAG=1
AND T.FAB= #{location,jdbcType=VARCHAR}
AND T.SHIFT_DATE=TO_CHAR(SYSDATE-8/24-1,'YYYYMMDD') GROUP BY T2.TECH )B ON A.TECH=B.TECH ), EQP_TARGET AS( SELECT 'Target'TECH,QA_ADI,QA_AEI,QA_AEI_CMP,QA_AFM,QB_BUBBLE ,QB_BUBBLE_STK,QC_THK,QC_THK_SI,QC_TRIM,QG_DEFECT,QP_DEFECT,QS_SEM,QW_SEM,QX_OVERLY,QY_D_PC,QZ_DEFECT ,NULL WIP FROM ( SELECT EQP_G,SR FROM A3MFGYW1.T_OPD_SR ) T PIVOT ( MAX(SR) FOR EQP_G IN ( 'QA_ADI' AS QA_ADI, 'QA_AEI' AS QA_AEI, 'QA_AEI_CMP' AS QA_AEI_CMP, 'QA_AFM' AS QA_AFM, 'QB_Bubble' AS QB_Bubble, 'QB_Bubble_STK' AS QB_Bubble_STK, 'QC_THK' AS QC_THK, 'QC_THK_Si' AS QC_THK_Si, 'QC_Trim' AS QC_Trim, 'QG_Defect' AS QG_Defect, 'QP_Defect' AS QP_Defect, 'QS_SEM' AS QS_SEM, 'QW_SEM' AS QW_SEM, 'QX_Overly' AS QX_Overly, 'QY_D.PC' AS QY_D_PC, -- 注意：列名不能有点号，改为下划线 'QZ_Defect' AS QZ_Defect ) ) ) SELECT TECH,QA_ADI,QA_AEI,QA_AEI_CMP,QA_AFM,QB_BUBBLE,QB_BUBBLE_STK,QC_THK,QC_THK_SI,QC_TRIM,QG_DEFECT,QP_DEFECT,QS_SEM,QW_SEM,QX_OVERLY,QY_D_PC,QZ_DEFECT,WIP FROM EQP_TARGET UNION ALL SELECT TECH,QA_ADI,QA_AEI,QA_AEI_CMP,QA_AFM,QB_BUBBLE,QB_BUBBLE_STK,QC_THK,QC_THK_SI,QC_TRIM,QG_DEFECT,QP_DEFECT,QS_SEM,QW_SEM,QX_OVERLY,QY_D_PC,QZ_DEFECT,WIP FROM SR_TEMP UNION ALL SELECT 'TTL' AS TECH , ROUND(SUM(QA_ADI*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QA_AEI*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QA_AEI_CMP*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QA_AFM*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QB_Bubble*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QB_Bubble_STK*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QC_THK*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QC_THK_Si*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QC_Trim*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QG_Defect*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QP_Defect*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QS_SEM*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QW_SEM*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QX_Overly*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QY_D_PC*T2.WIP)/SUM(T2.WIP),2), ROUND(SUM(QZ_Defect*T2.WIP)/SUM(T2.WIP),2), SUM(WIP) FROM SR_TEMP T2

WITH SR_DATA AS ( SELECT * FROM ( SELECT T.PRODG1, NVL(T.EQP_G_NEW, T.EQP_G) AS EQP_G, CASE WHEN SUM(WIP) OVER (PARTITION BY T2.PRODG1, NVL(T.EQP_G_NEW, T.EQP_G)) > 0 THEN ROUND(SUM(PSTD_SR * WIP) OVER (PARTITION BY T2.PRODG1, NVL(T.EQP_G_NEW, T.EQP_G)) / SUM(WIP) OVER (PARTITION BY T2.PRODG1, NVL(T.EQP_G_NEW, T.EQP_G)), 3) ELSE NULL END AS PSTD_SR FROM A3MFGYW1.T_MFG_SR_KPI T INNER JOIN A3MFGYW1.PRODG_INFO T2 ON T.PRODG1 = T2.PRODG1 AND T.FAB = T2.FAB WHERE T.SHIFT_DATE = TO_CHAR(SYSDATE-8/24-1, 'YYYYMMDD')
AND T.FAB= #{location,jdbcType=VARCHAR}
AND T2.TECH= #{tech,jdbcType=VARCHAR}
AND T.PRODUCT_STATUS IN
#{item,jdbcType=VARCHAR}
) PIVOT ( MAX(PSTD_SR) FOR EQP_G IN ( 'QA_ADI' AS QA_ADI, 'QA_AEI' AS QA_AEI, 'QA_AEI_CMP' AS QA_AEI_CMP, 'QA_AFM' AS QA_AFM, 'QB_Bubble' AS QB_Bubble, 'QB_Bubble_STK' AS QB_Bubble_STK, 'QC_THK' AS QC_THK, 'QC_THK_Si' AS QC_THK_Si, 'QC_Trim' AS QC_Trim, 'QG_Defect' AS QG_Defect, 'QP_Defect' AS QP_Defect, 'QS_SEM' AS QS_SEM, 'QW_SEM' AS QW_SEM, 'QX_Overly' AS QX_Overly, 'QY_D.PC' AS QY_D_PC, 'QZ_Defect' AS QZ_Defect ) ) ORDER BY PRODG1 ), SR_TEMP AS( SELECT A.*,B.WIP FROM SR_DATA A LEFT JOIN ( SELECT T.PRODG1,SUM(T.WAFER_QTY) AS WIP FROM A3MFGYW1.LOT_PRIORITY_HISTORY T WHERE T.SHIFT_HOUR = '01' and t.NENG_FLAG=1
AND T.FAB= #{location,jdbcType=VARCHAR}
AND T.SHIFT_DATE=TO_CHAR(SYSDATE-8/24-1,'YYYYMMDD') GROUP BY T.PRODG1 )B ON A.PRODG1=B.PRODG1 ) SELECT PRODG1,QA_ADI,QA_AEI,QA_AEI_CMP,QA_AFM,QB_BUBBLE,QB_BUBBLE_STK,QC_THK,QC_THK_SI,QC_TRIM,QG_DEFECT,QP_DEFECT,QS_SEM,QW_SEM,QX_OVERLY,QY_D_PC,QZ_DEFECT ,WIP FROM SR_TEMP

SELECT DISTINCT EQP_G label,EQP_G value FROM  A3MFGYW1.T_MFG_MEA_SR
WHERE 1=1

    AND LOCATION = #{fab}

SELECT DISTINCT PRODG1 label,PRODG1 value FROM  A3MFGYW1.T_MFG_MEA_SR
WHERE 1=1

    AND LOCATION = #{fab}


    AND TECH = #{tech}


    AND EQP_G = #{eqpg}

SELECT SHIFT_DATE,MODULE,FAB,EQP_G ,COUNT(1)TTL_COUNT ,SUM(SON_START_TARGET_FLAG)SON_START_TARGET_COUNT ,SUM(PARENT_START_TARGET_FLAG)PARENT_START_TARGET_COUNT ,SUM(SON_MERGE_TARGET_FLAG)SON_MERGE_TARGET_COUNT ,SUM(PARENT_MERGE_TARGET_FLAG)PARENT_MERGE_TARGET_COUNT FROM( SELECT SHIFT_DATE,MODULE,FAB,EQP_G ,CASE WHEN SON_START_ACT_TIME<= SON_START_STD_TIME THEN 1 ELSE 0 END SON_START_TARGET_FLAG ,CASE WHEN PARENT_START_ACT_TIME<=PARENT_START_STD_TIME THEN 1 ELSE 0 END PARENT_START_TARGET_FLAG ,CASE WHEN SON_MERGE_ACT_TIME<=SON_MERGE_STD_TIME THEN 1 ELSE 0 END SON_MERGE_TARGET_FLAG ,CASE WHEN PARENT_MERGE_ACT_TIME<=PARENT_MERGE_STD_TIME THEN 1 ELSE 0 END PARENT_MERGE_TARGET_FLAG FROM A1_MFG.PILOT_RUN_DETAIL WHERE NVL(PIRUN_TYPE,'N') <>'PM' AND SHIFT_DATE = #{shiftDate} AND FAB = #{fab} AND MODULE =#{module}
AND PARENT_START_TYPE = 'NOPATH'
AND PARENT_MERGE_TYPE = 'NOPATH'
AND PARENT_START_TYPE = '有PATH'
AND PARENT_MERGE_TYPE = '有PATH'
)GROUP BY SHIFT_DATE,MODULE,FAB,EQP_G

SELECT A.SHIFT_DATE,NVL(B.MOVE_PARENT,A.MOVE_PARENT) MOVE_PARENT, NVL(B.MOVE_SON,A.MOVE_SON) MOVE_SON, NVL(B.EQPG_TOTAL_COUNT,A.EQPG_TOTAL_COUNT) EQPG_TOTAL_COUNT, NVL(B.EQPG_TOTAL_MOVE,A.EQPG_TOTAL_MOVE) EQPG_TOTAL_MOVE, NVL(B.REWORK_COUNT,A.REWORK_COUNT) REWORK_COUNT, NVL(B.REWORK_COUNT_RATIO,A.REWORK_COUNT_RATIO) REWORK_COUNT_RATIO, NVL(B.MOVE_PARENT_RATIO,A.MOVE_PARENT_RATIO) MOVE_PARENT_RATIO, NVL(B.MOVE_SON_RATIO,A.MOVE_SON_RATIO) MOVE_SON_RATIO,NVL(B.TARGET,A.TARGET) TARGET FROM ( SELECT TO_CHAR(SYSDATE-LEVEL, 'YYYYMMDD') AS SHIFT_DATE,0 AS MOVE_PARENT,0 MOVE_SON,0 EQPG_TOTAL_COUNT,0 EQPG_TOTAL_MOVE,0 REWORK_COUNT,0 REWORK_COUNT_RATIO,0 MOVE_PARENT_RATIO,0 MOVE_SON_RATIO,0 TARGET FROM DUAL CONNECT BY LEVEL <= 30 ) A LEFT JOIN ( SELECT A.SHIFT_DATE,A.MOVE_PARENT,A.MOVE_SON,A.EQPG_TOTAL_COUNT, A.EQPG_TOTAL_MOVE, A.REWORK_COUNT,A.REWORK_COUNT_RATIO,A.MOVE_PARENT_RATIO, A.MOVE_SON_RATIO,A.TARGET*100 TARGET FROM ( SELECT A.SHIFT_DATE,SUM(MOVE_PARENT) MOVE_PARENT,SUM(MOVE_SON) MOVE_SON,SUM(EQPG_TOTAL_COUNT) EQPG_TOTAL_COUNT ,SUM(EQPG_TOTAL_MOVE) EQPG_TOTAL_MOVE,SUM(REWORK_COUNT) REWORK_COUNT, CASE WHEN SUM(EQPG_TOTAL_COUNT)=0 THEN 0 ELSE ROUND(SUM(REWORK_COUNT)/SUM(EQPG_TOTAL_COUNT),4)*100 END REWORK_COUNT_RATIO, CASE WHEN SUM(EQPG_TOTAL_MOVE)=0 THEN 0 ELSE ROUND(SUM(MOVE_PARENT)/SUM(EQPG_TOTAL_MOVE),4)*100 END MOVE_PARENT_RATIO, CASE WHEN SUM(EQPG_TOTAL_MOVE)=0 THEN 0 ELSE ROUND(SUM(MOVE_SON)/SUM(EQPG_TOTAL_MOVE),4)*100 END MOVE_SON_RATIO, CASE WHEN SUM(A.EQPG_TOTAL_MOVE)=0 THEN SUM(A.TARGET) ELSE ROUND(SUM(A.EQPG_TOTAL_MOVE*A.TARGET)/SUM(A.EQPG_TOTAL_MOVE),3) END TARGET FROM ( SELECT A.SHIFT_DATE,A.EQP_G,SUM(REWORK_COUNT) REWORK_COUNT,SUM(A.MOVE_SON) MOVE_SON,SUM(A.MOVE_PARENT) MOVE_PARENT,SUM(A.EQPG_TOTAL_COUNT) EQPG_TOTAL_COUNT, SUM(A.EQPG_TOTAL_MOVE) EQPG_TOTAL_MOVE, MAX(TARGET) TARGET FROM ( SELECT A.SHIFT_DATE,A.EQP_G,A.LOCATION,A.MODULE,A.REWORK_COUNT,A.MOVE_SON,A.MOVE_PARENT,A.EQPG_TOTAL_COUNT,A.EQPG_TOTAL_MOVE FROM A3MFGYW1.EQPG_REWORK_SUMMARY A WHERE 1=1
AND A.LOCATION = #{fab}
AND A.MODULE = DECODE(#{module},'METRO','Measurement',#{module})
AND A.EQP_G = #{eqpg}
) A LEFT JOIN ( SELECT SHIFT_DATE,KEY1 MODULE,KEY2 TARGET,KEY3 EQP_G FROM A1_MFG.CRITICLE_COMMENT_SUMMARY_HS B WHERE FUNCTION_NAME = 'Rework Target' ) B ON A.EQP_G= B.EQP_G AND A.SHIFT_DATE = B.SHIFT_DATE GROUP BY A.SHIFT_DATE,A.EQP_G ) A GROUP BY A.SHIFT_DATE )A ) B ON A.SHIFT_DATE = B.SHIFT_DATE ORDER BY A.SHIFT_DATE

SELECT A.SHIFT_DATE,A.FAB,A.LOCATION,A.MODULE,A.TECH,A.PRODG1,A.PRODSPEC_ID,A.LOT_ID,A.OPE_NO,A.WAFER_QTY,A.PARENT_LOT_ID,A.PARENT_WAFER_QTY,A.EQP_ID,A.EQP_G
FROM A3MFGYW1.EQPG_REWORK_MOVE_SUMMARY A
WHERE SHIFT_DATE = #{shiftDate}

    AND LOCATION = #{fab}


    AND MODULE = DECODE(#{module},'METRO','Measurement',#{module})


    AND EQP_G = #{eqpg}

ORDER BY MODULE, EQP_G,EQP_ID

SELECT A.SHIFT_DATE,NVL(B.RATIO,A.RATIO) HOLD_RATIO,NVL(B.DUR,A.DUR) HOLD_TIME ,C.HOLD_TIME_TARGET ,D.HOLD_RATIO_TARGET FROM ( SELECT TO_CHAR(SYSDATE-LEVEL, 'YYYYMMDD') AS SHIFT_DATE,0 AS RATIO,0 AS DUR FROM DUAL CONNECT BY LEVEL <= 30 ) A LEFT JOIN ( SELECT SHIFT_DATE,ROUND(AVG(RATIO),4)*100 RATIO,ROUND(AVG(DUR),2) DUR FROM A3MFGYW1.EQPG_REDEPO_SUMMARY WHERE 1=1
AND LOCATION = #{fab}
AND MODULE = DECODE(#{module},'METRO','Measurement',#{module})
AND EQP_G = #{eqpg}
GROUP BY SHIFT_DATE ) B ON A.SHIFT_DATE = B.SHIFT_DATE LEFT JOIN ( SELECT SHIFT_DATE,KEY2 HOLD_TIME_TARGET FROM A1_MFG.CRITICLE_COMMENT_SUMMARY_HS WHERE FUNCTION_NAME ='ReProcess Monitor Dur Target' )C ON A.SHIFT_DATE = C.SHIFT_DATE LEFT JOIN( SELECT SHIFT_DATE,KEY2*100 HOLD_RATIO_TARGET FROM A1_MFG.CRITICLE_COMMENT_SUMMARY_HS WHERE FUNCTION_NAME ='ReProcess Monitor ratio Target' )D ON A.SHIFT_DATE = D.SHIFT_DATE ORDER BY A.SHIFT_DATE

SELECT LOT_ID,SHIFT_DATE,HOLD_CODE,HOLD_COMMENT,WAFER_QTY,OPE_NO,PRODSPEC_ID,EQP_ID,EQP_G,MODULE,DUR
FROM A3MFGYW1.EQPG_REDEPO_SUMMARY
WHERE SHIFT_DATE=#{shiftDate}

    AND LOCATION = #{fab}


    AND MODULE = DECODE(#{module},'METRO','Measurement',#{module})


    AND EQP_G = #{eqpg}

SELECT KEY1 MODULE,KEY2 TARGET,KEY3 EQP_G FROM A1_MFG.CRITICLE_COMMENT_SUMMARY
WHERE FUNCTION_NAME ='Rework Target'

    AND KEY1 = #{module}

UPDATE A1_MFG.CRITICLE_COMMENT_SUMMARY
SET KEY2 = #{target},UPDATE_USER = #{updateUser},UPDATE_TIME = SYSDATE
WHERE FUNCTION_NAME ='Rework Target' AND KEY1 = #{module} AND KEY3 = #{eqpg}

SELECT C1.OPER_NO,C1.OPER_SEQ,C1.STD_SR,C1.ACT_SR,C2.TOTAL_COUNT,C2.NG_RATIO
FROM (
SELECT OPER_NO,AVG(OPER_SEQ) OPER_SEQ,
CASE WHEN SUM(TOTAL_COUNT)>0 THEN ROUND(100*NVL(SUM(SR*TOTAL_COUNT)/SUM(TOTAL_COUNT),AVG(SR)),1) END STD_SR,
CASE WHEN SUM(TOTAL_COUNT)>0 THEN ROUND(100*NVL(SUM(ACT_SR*TOTAL_COUNT)/SUM(TOTAL_COUNT),AVG(ACT_SR)),1) END ACT_SR
FROM (
SELECT B1.FAB,B1.PRODG1,B1.OPER_NO,B1.OPER_SEQ,B1.SR,B2.TOTAL_COUNT,B2.ACT_SR
FROM (
SELECT A1.FAB,A1.PRODG1,A1.OPER_NO,A1.OPER_SEQ,A1.SR,A1.EQP_G,A2.TECH
FROM A3MFGYW1.FLOW_STD_CYCLE_TIME A1,
A3MFGYW1.PRODG_INFO A2
WHERE A1.FAB=A2.FAB AND A1.PRODG1=A2.PRODG1
AND A1.EQP_G=#{eqpg}

    AND A2.TECH=#{tech}


    AND A2.PRODG1=#{prodg}

)B1,
(
SELECT LOCATION,PRODG1,OPE_NO,COUNT(EQP_ID) TOTAL_COUNT,COUNT(EQP_ID)/COUNT(1) ACT_SR
FROM A3MFGYW1.MOVE_SUMMARY
WHERE 1=1

    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')


    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-7,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')


    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-3,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')

AND EQP_G=#{eqpg}

    AND TECH=#{tech}


    AND PRODG1=#{prodg}

GROUP BY LOCATION,PRODG1,OPE_NO
)B2
WHERE B1.FAB=B2.LOCATION AND B1.PRODG1=B2.PRODG1(+) AND B1.OPER_NO=B2.OPE_NO(+)

    AND B1.FAB=#{fab}

)
GROUP BY OPER_NO
)C1,
(
SELECT B1.OPE_NO,B1.TOTAL_COUNT,NVL(B2.NG_COUNT,0) NG_COUNT,CASE WHEN B1.TOTAL_COUNT>0 THEN LEAST(ROUND(100*NVL(B2.NG_COUNT,0)/B1.TOTAL_COUNT,1),100) END NG_RATIO
FROM (
SELECT OPE_NO,COUNT(1) TOTAL_COUNT
FROM A3MFGYW1.MOVE_SUMMARY
WHERE EQP_ID IS NOT NULL

    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')


    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-7,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')


    AND SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24-3,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24-1,'YYYYMMDD')

AND EQP_G=#{eqpg}

    AND TECH=#{tech}


    AND PRODG1=#{prodg}


    AND LOCATION=#{fab}

GROUP BY OPE_NO
)B1,
(
SELECT OPE_NO,COUNT(1) NG_COUNT
FROM (
SELECT DISTINCT TO_CHAR(A1.CLAIM_TIME-7.5/24,'YYYYMMDD') SHIFT_DATE,A1.LOCATION,A1.LOT_ID,A1.RESPONSIBLE_OPE_NO OPE_NO,A1.PRODG1,
A1.CLAIM_TIME,A1.RELEASE_TIME,A2.EQP_G,A3.TECH
FROM A3MFGYW1.HOLD_SUMMARY A1,
A3MFGYW1.FLOW_STD_CYCLE_TIME A2,
A3MFGYW1.PRODG_INFO A3
WHERE A1.FAB=A2.FAB(+) AND A1.PRODG1=A2.PRODG1(+) AND A1.RESPONSIBLE_OPE_NO=A2.OPER_NO(+)
AND A1.FAB=A3.FAB(+) AND A1.PRODG1=A3.PRODG1(+)
AND A1.HOLD_TYPE IN ('SpecOverHold','SPCOutOfRangeHold')

    AND A1.CLAIM_TIME BETWEEN TRUNC(SYSDATE-7.5/24-30)+7.5/24 AND TRUNC(SYSDATE-7.5/24)+7.5/24


    AND A1.CLAIM_TIME BETWEEN TRUNC(SYSDATE-7.5/24-7)+7.5/24 AND TRUNC(SYSDATE-7.5/24)+7.5/24


    AND A1.CLAIM_TIME BETWEEN TRUNC(SYSDATE-7.5/24-3)+7.5/24 AND TRUNC(SYSDATE-7.5/24)+7.5/24

AND A2.EQP_G=#{eqpg}

AND A3.TECH=#{tech}


    AND A1.PRODG1=#{prodg}


    AND A1.LOCATION=#{fab}

)
GROUP BY OPE_NO
)B2
WHERE B1.OPE_NO=B2.OPE_NO(+)
)C2
WHERE C1.OPER_NO=C2.OPE_NO
ORDER BY C1.OPER_SEQ

SELECT CASE WHEN A.FLAG = 1 THEN A.SHIFT_DATE || '_AVG' WHEN A.FLAG =2 THEN A.SHIFT_DATE END SHIFT_DATE ,NVL(C.TOTAL_TIME,B.TOTAL_TIME) TOTAL_TIME,NVL(C.ADD_TEST_RUNTIME,B.ADD_TEST_RUNTIME) ADD_TEST_RUNTIME,NVL(C.RE_TEST_RUNTIME,B.RE_TEST_RUNTIME) RE_TEST_RUNTIME, NVL(C.INLINE_TIME,B.INLINE_TIME) INLINE_TIME,NVL(C.ADD_TEST_RATIO,B.ADD_TEST_RATIO) ADD_TEST_RATIO,NVL(C.RE_TEST_RATIO,B.RE_TEST_RATIO) RE_TEST_RATIO,A.ADD_TEST_RATIO_TARGET,A.RE_TEST_RATIO_TARGET FROM ( SELECT TO_CHAR(ADD_MONTHS(SYSDATE, LEVEL - 2), 'YYYYMM') AS SHIFT_DATE,0 AS RATIO,3 RE_TEST_RATIO_TARGET,5 ADD_TEST_RATIO_TARGET,1 FLAG FROM DUAL CONNECT BY LEVEL <= 2 UNION ALL SELECT TO_CHAR(SYSDATE-LEVEL, 'YYYYMMDD') AS SHIFT_DATE,0 AS RATIO,3 RE_TEST_RATIO_TARGET,5 ADD_TEST_RATIO_TARGET,2 FLAG FROM DUAL CONNECT BY LEVEL <= 30 ) A LEFT JOIN ( SELECT SHIFT_MONTH SHIFT_DATE,ROUND(AVG(TOTAL_TIME),2) TOTAL_TIME,0 ADD_TEST_RUNTIME,0 RE_TEST_RUNTIME,ROUND(AVG(TOTAL_TIME),2) INLINE_TIME, 0 ADD_TEST_RATIO,0 RE_TEST_RATIO FROM ( SELECT SUBSTR(SHIFT_DATE,1,6) SHIFT_MONTH,SHIFT_DATE,ROUND(SUM(TOTAL_TIME),2) TOTAL_TIME,0 ADD_TEST_RUNTIME,0 RE_TEST_RUNTIME,ROUND(SUM(TOTAL_TIME),2) INLINE_TIME, 0 ADD_TEST_RATIO,0 RE_TEST_RATIO FROM ( SELECT 'N1A3' LOCATION, A.SHIFT_DATE,A.EQP_G,(A.PRD_TIME_DTH+A.SBY_TIME_DTH+A.ENG_TIME_DTH)*24 TOTAL_TIME FROM ( SELECT A.*,ROW_NUMBER()OVER(PARTITION BY SHIFT_DATE,EQP_G ORDER BY UPDATE_TIME) RN FROM PWEB.V_EQPG_MOVE_STATUS_DAILY_OCS@A3PDW A ) A WHERE A.RN=1 UNION ALL SELECT 'N1A1' LOCATION, B.SHIFT_DATE,B.EQP_G,(B.PRD_TIME_DTH+B.SBY_TIME_DTH+B.ENG_TIME_DTH)*24 TOTAL_TIME FROM ( SELECT A.*,ROW_NUMBER()OVER(PARTITION BY SHIFT_DATE,EQP_G ORDER BY UPDATE_TIME) RN FROM PWEB.V_EQPG_MOVE_STATUS_DAILY_OCS@A1PDW A ) B WHERE B.RN=1 ) A --放查询条件 WHERE A.EQP_G='WAT_Tester'
AND A.LOCATION=#{fab}
GROUP BY A.SHIFT_DATE ) GROUP BY SHIFT_MONTH UNION ALL SELECT SHIFT_DATE,ROUND(SUM(TOTAL_TIME),2) TOTAL_TIME,0 ADD_TEST_RUNTIME,0 RE_TEST_RUNTIME,ROUND(SUM(TOTAL_TIME),2) INLINE_TIME, 0 ADD_TEST_RATIO,0 RE_TEST_RATIO FROM ( SELECT 'N1A3' LOCATION, A.SHIFT_DATE,A.EQP_G,(A.PRD_TIME_DTH+A.SBY_TIME_DTH+A.ENG_TIME_DTH)*24 TOTAL_TIME FROM ( SELECT A.*,ROW_NUMBER()OVER(PARTITION BY SHIFT_DATE,EQP_G ORDER BY UPDATE_TIME) RN FROM PWEB.V_EQPG_MOVE_STATUS_DAILY_OCS@A3PDW A ) A WHERE A.RN=1 UNION ALL SELECT 'N1A1' LOCATION, B.SHIFT_DATE,B.EQP_G,(B.PRD_TIME_DTH+B.SBY_TIME_DTH+B.ENG_TIME_DTH)*24 TOTAL_TIME FROM ( SELECT A.*,ROW_NUMBER()OVER(PARTITION BY SHIFT_DATE,EQP_G ORDER BY UPDATE_TIME) RN FROM PWEB.V_EQPG_MOVE_STATUS_DAILY_OCS@A1PDW A ) B WHERE B.RN=1 ) A --放查询条件 WHERE 1=1 AND A.EQP_G='WAT_Tester'
AND A.LOCATION=#{fab}
GROUP BY SHIFT_DATE ) B ON A.SHIFT_DATE=B.SHIFT_DATE LEFT JOIN ( SELECT SHIFT_MONTH SHIFT_DATE,ROUND(AVG(TOTAL_TIME),2) TOTAL_TIME,ROUND(AVG(ADD_TEST_RUNTIME),2) ADD_TEST_RUNTIME,ROUND(AVG(RE_TEST_RUNTIME),2) RE_TEST_RUNTIME,ROUND(AVG(INLINE_TIME),2) INLINE_TIME, ROUND(SUM(ADD_TEST_RUNTIME)/SUM(TOTAL_TIME),4)*100 ADD_TEST_RATIO, ROUND(SUM(RE_TEST_RUNTIME)/SUM(TOTAL_TIME),4)*100 RE_TEST_RATIO FROM ( SELECT SUBSTR(SHIFT_DATE,1,6) SHIFT_MONTH,SHIFT_DATE,SUM(TOTAL_TIME) TOTAL_TIME,SUM(ADD_TEST_RUNTIME) ADD_TEST_RUNTIME,SUM(RE_TEST_RUNTIME) RE_TEST_RUNTIME , SUM(TOTAL_TIME)-SUM(ADD_TEST_RUNTIME)-SUM(RE_TEST_RUNTIME) INLINE_TIME FROM ( SELECT SHIFT_DATE,EQP_G,LOCATION, MAX(TOTAL_TIME) TOTAL_TIME, SUM(CASE WHEN TEST_TYPE='A' THEN DURATION ELSE 0 END) ADD_TEST_RUNTIME, SUM(CASE WHEN TEST_TYPE='R' THEN DURATION ELSE 0 END) RE_TEST_RUNTIME FROM A3MFGYW1.EQPG_WAT_TEST_SUMMARY --放查询条件 WHERE SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24 -90,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD')
AND LOCATION=#{fab}
GROUP BY SHIFT_DATE,EQP_G,LOCATION ) GROUP BY SHIFT_DATE ) GROUP BY SHIFT_MONTH UNION ALL SELECT SHIFT_DATE,SUM(TOTAL_TIME) TOTAL_TIME,SUM(ADD_TEST_RUNTIME) ADD_TEST_RUNTIME,SUM(RE_TEST_RUNTIME) RE_TEST_RUNTIME , SUM(TOTAL_TIME)-SUM(ADD_TEST_RUNTIME)-SUM(RE_TEST_RUNTIME) INLINE_TIME, ROUND(SUM(ADD_TEST_RUNTIME)/SUM(TOTAL_TIME),4)*100 ADD_TEST_RATIO, ROUND(SUM(RE_TEST_RUNTIME)/SUM(TOTAL_TIME),4)*100 RE_TEST_RATIO FROM ( SELECT SHIFT_DATE,EQP_G,LOCATION, MAX(TOTAL_TIME) TOTAL_TIME, SUM(CASE WHEN TEST_TYPE='A' THEN DURATION ELSE 0 END) ADD_TEST_RUNTIME, SUM(CASE WHEN TEST_TYPE='R' THEN DURATION ELSE 0 END) RE_TEST_RUNTIME FROM A3MFGYW1.EQPG_WAT_TEST_SUMMARY --放查询条件 WHERE SHIFT_DATE BETWEEN TO_CHAR(SYSDATE-7.5/24 -30,'YYYYMMDD') AND TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD')
AND LOCATION=#{fab}
GROUP BY SHIFT_DATE,EQP_G,LOCATION ) GROUP BY SHIFT_DATE ) C ON A.SHIFT_DATE = C.SHIFT_DATE ORDER BY A.FLAG,A.SHIFT_DATE

SELECT LOCATION, FAB, LOT_ID, SHIFT_DATE, OPE_NO, NG_FLAG_WMS
, FINAL_JUDGE, PRODG, PRODUCT_OWNER_DEPT, TEST_PROGRAM, NUM_WAFER_TESTED
, NUM_WAFER_PASSED, NUM_WAFER_NG, PRODUCT_ID, EQUIPMENT_ID, PROCESS_START_TIME
, MEASURE_TIME, FAB_ID, EMPLOYEE_ID, PROBECARD, MA_REASON,TEST_TYPE, DURATION
FROM A3MFGYW1.EQPG_WAT_TEST_SUMMARY
WHERE 1=1

    AND SUBSTR(SHIFT_DATE,1,6) = #{shiftDate}


    AND SHIFT_DATE= #{shiftDate}


    AND LOCATION = #{fab}

SELECT A.PRIORITY_TYPE,A.TARGET,NVL(B.WIP,0) WIP,SUM(NVL(B.WIP,0))OVER(ORDER BY 1) TOTAL_WIP, ROUND(100*NVL(B.WIP,0)/SUM(NVL(B.WIP,0))OVER(ORDER BY 1),1) RATIO FROM ( SELECT 'PRI_'||MIN_PRIORITY||'_'||MAX_PRIORITY PRIORITY_TYPE,TARGET,PUSH_PRIORITY FROM A3MFGYW1.LOT_PRIORITY_TARGET )A, ( SELECT PRIORITY_TYPE,SUM(WAFER_QTY) WIP FROM ( SELECT A.FAB,A.LOCATION,A.LOT_ID,A.WAFER_QTY,A.LOT_PRIORITY, CASE WHEN LOT_PRIORITY<=99 THEN 'PRI_1_99' WHEN LOT_PRIORITY>99 AND LOT_PRIORITY<=199 THEN 'PRI_100_199' WHEN LOT_PRIORITY>199 AND LOT_PRIORITY<=299 THEN 'PRI_200_299' WHEN LOT_PRIORITY>299 AND LOT_PRIORITY<=399 THEN 'PRI_300_399' WHEN LOT_PRIORITY>399 AND LOT_PRIORITY<=499 THEN 'PRI_400_499' WHEN LOT_PRIORITY>499 AND LOT_PRIORITY<=599 THEN 'PRI_500_599' WHEN LOT_PRIORITY>599 AND LOT_PRIORITY<=699 THEN 'PRI_600_699' WHEN LOT_PRIORITY>699 AND LOT_PRIORITY<=799 THEN 'PRI_700_799' WHEN LOT_PRIORITY>799 AND LOT_PRIORITY<=899 THEN 'PRI_800_899' WHEN LOT_PRIORITY>899 THEN 'PRI_900_999' END PRIORITY_TYPE FROM A3MFGYW1.LOT_PRIORITY_HISTORY A, A3MFGYW1.PRODG_INFO B WHERE A.FAB=B.FAB AND A.PRODG1=B.PRODG1 AND TO_CHAR(A.UPDATE_TIME,'YYYYMMDD')=nvl(#{shiftDate},TO_CHAR(SYSDATE,'YYYYMMDD')) AND TO_CHAR(A.UPDATE_TIME,'HH24')||':30'=nvl(#{hour},TO_CHAR(SYSDATE-0.5/24,'HH24')||':30')
AND A.FAB = #{fab}
AND A.LOCATION = #{location}
AND B.TECH = #{tech}
) GROUP BY PRIORITY_TYPE )B WHERE A.PRIORITY_TYPE=B.PRIORITY_TYPE(+) ORDER BY A.PUSH_PRIORITY

SELECT SUBSTR(SHIFT_TIME,5) SHIFT_DATE,PRIORITY_TYPE,TOTAL,PRIORITY_QTY, ROUND(100*PRIORITY_QTY/TOTAL,1) RATIO,TARGET FROM ( SELECT A.SHIFT_TIME,A.TOTAL,A.PRIORITY_QTY,A.PRIORITY_TYPE,B.TARGET FROM ( SELECT SHIFT_TIME,SUM(WAFER_QTY) TOTAL,SUM(DECODE(PRIORITY_TYPE,#{priority},WAFER_QTY,0)) PRIORITY_QTY ,#{priority} PRIORITY_TYPE FROM ( SELECT TO_CHAR(A.UPDATE_TIME,'YYYYMMDD')||' '||TO_CHAR(A.UPDATE_TIME,'HH24')||':30' SHIFT_TIME, A.FAB,A.LOCATION,A.LOT_ID,A.WAFER_QTY,A.LOT_PRIORITY, CASE WHEN LOT_PRIORITY<=99 THEN 'PRI_1_99' WHEN LOT_PRIORITY>99 AND LOT_PRIORITY<=199 THEN 'PRI_100_199' WHEN LOT_PRIORITY>199 AND LOT_PRIORITY<=299 THEN 'PRI_200_299' WHEN LOT_PRIORITY>299 AND LOT_PRIORITY<=399 THEN 'PRI_300_399' WHEN LOT_PRIORITY>399 AND LOT_PRIORITY<=499 THEN 'PRI_400_499' WHEN LOT_PRIORITY>499 AND LOT_PRIORITY<=599 THEN 'PRI_500_599' WHEN LOT_PRIORITY>599 AND LOT_PRIORITY<=699 THEN 'PRI_600_699' WHEN LOT_PRIORITY>699 AND LOT_PRIORITY<=799 THEN 'PRI_700_799' WHEN LOT_PRIORITY>799 AND LOT_PRIORITY<=899 THEN 'PRI_800_899' WHEN LOT_PRIORITY>899 THEN 'PRI_900_999' END PRIORITY_TYPE FROM A3MFGYW1.LOT_PRIORITY_HISTORY A, A3MFGYW1.PRODG_INFO B WHERE A.FAB=B.FAB AND A.PRODG1=B.PRODG1 AND A.SHIFT_DATE >= CASE WHEN #{startDate,jdbcType=VARCHAR} IS NOT NULL THEN #{startDate} WHEN #{endDate,jdbcType=VARCHAR} IS NOT NULL THEN TO_CHAR(TO_DATE(#{endDate},'YYYYMMDD')-2,'YYYYMMDD') ELSE TO_CHAR(SYSDATE-7.5/24-2,'YYYYMMDD') END AND A.SHIFT_DATE <= CASE WHEN #{endDate,jdbcType=VARCHAR} IS NOT NULL THEN #{endDate} ELSE TO_CHAR(SYSDATE-7.5/24,'YYYYMMDD') END
AND A.FAB = #{fab}
AND A.LOCATION = #{location}
AND B.TECH = #{tech}
) GROUP BY SHIFT_TIME )A, ( SELECT 'PRI_'||MIN_PRIORITY||'_'||MAX_PRIORITY AS PRIORITY_TYPE,TARGET,PUSH_PRIORITY FROM A3MFGYW1.LOT_PRIORITY_TARGET )B WHERE A.PRIORITY_TYPE=B.PRIORITY_TYPE(+) ) ORDER BY SHIFT_TIME

SELECT SHIFT_MONTH,MOVE,CRACK,NVL(RATIO,0)RATIO FROM ( SELECT SHIFT_MONTH,ROUND(AVG(MOVE)) MOVE,ROUND(AVG(CRACK)) CRACK, ROUND(100*(CASE WHEN AVG(MOVE)>0 THEN AVG(CRACK)/AVG(MOVE) END),1) RATIO FROM ( SELECT SUBSTR(A1.SHIFT_DATE,1,6) SHIFT_MONTH,A1.SHIFT_DATE,A1.MOVE,NVL(A2.CRACK,0) CRACK, ROUND(100*(CASE WHEN A1.MOVE>0 THEN NVL(A2.CRACK,0)/A1.MOVE END),1) RATIO FROM ( SELECT SHIFT_DATE,SUM(MOVE_COUNT) MOVE FROM A3MFGYW1.EQPG_MOVE_COUNT WHERE SHIFT_DATE>=TO_CHAR(TRUNC(SYSDATE-7.5/24-1,'YYYY'),'YYYYMMDD') --AND LOCATION='N1A3' GROUP BY SHIFT_DATE )A1, ( SELECT SHIFT_DATE,COUNT(CHILD_QTY) CRACK FROM ( SELECT SHIFT_DATE,CHILD_LOT_ID,CHILD_QTY,EQP_ID,EQPG_MOVE,EQPG_COUNT FROM A3MFGYW1.CRACK_LOT WHERE SHIFT_DATE>=TO_CHAR(TRUNC(SYSDATE-7.5/24-1,'YYYY'),'YYYYMMDD') -- AND EQP_ID = 'CSD302'
AND EQP_ID=#{eqpId}
) GROUP BY SHIFT_DATE )A2 WHERE A1.SHIFT_DATE=A2.SHIFT_DATE(+) ) GROUP BY SHIFT_MONTH UNION ALL SELECT A1.SHIFT_DATE,A1.MOVE,NVL(A2.CRACK,0) CRACK, ROUND(100*(CASE WHEN A1.MOVE>0 THEN NVL(A2.CRACK,0)/A1.MOVE END),1) RATIO FROM ( SELECT SHIFT_DATE,SUM(MOVE_COUNT) MOVE FROM A3MFGYW1.EQPG_MOVE_COUNT WHERE SHIFT_DATE>=TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') --AND LOCATION='N1A3' GROUP BY SHIFT_DATE )A1, ( SELECT SHIFT_DATE,COUNT(CHILD_QTY) CRACK FROM ( SELECT SHIFT_DATE,CHILD_LOT_ID,CHILD_QTY,EQP_ID,EQPG_MOVE,EQPG_COUNT FROM A3MFGYW1.CRACK_LOT WHERE SHIFT_DATE>=TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') -- AND EQP_ID = 'CSD302'
AND EQP_ID=#{eqpId}
) GROUP BY SHIFT_DATE )A2 WHERE A1.SHIFT_DATE=A2.SHIFT_DATE(+) ) ORDER BY LENGTH(SHIFT_MONTH),SHIFT_MONTH

SELECT SHIFT_MONTH,MOVE,CRACK,NVL(RATIO,0)RATIO FROM ( SELECT SHIFT_MONTH,ROUND(AVG(MOVE)) MOVE,ROUND(AVG(CRACK)) CRACK, ROUND(100*(CASE WHEN AVG(MOVE)>0 THEN AVG(CRACK)/AVG(MOVE) END),1) RATIO FROM ( SELECT SUBSTR(A1.SHIFT_DATE,1,6) SHIFT_MONTH,A1.SHIFT_DATE,A1.MOVE,NVL(A2.CRACK,0) CRACK, ROUND(100*(CASE WHEN A1.MOVE>0 THEN NVL(A2.CRACK,0)/A1.MOVE END),1) RATIO FROM ( SELECT SHIFT_DATE,SUM(MOVE) MOVE FROM A3MFGYW1.EQPG_MOVE_COUNT WHERE SHIFT_DATE>=TO_CHAR(TRUNC(SYSDATE-7.5/24-1,'YYYY'),'YYYYMMDD') --AND LOCATION='N1A3' GROUP BY SHIFT_DATE )A1, ( SELECT SHIFT_DATE,SUM(CHILD_QTY) CRACK FROM ( SELECT SHIFT_DATE,CHILD_LOT_ID,CHILD_QTY,EQP_ID,EQPG_MOVE,EQPG_COUNT FROM A3MFGYW1.CRACK_LOT WHERE SHIFT_DATE>=TO_CHAR(TRUNC(SYSDATE-7.5/24-1,'YYYY'),'YYYYMMDD') -- AND EQP_ID = 'CSD302'
AND EQP_ID=#{eqpId}
) GROUP BY SHIFT_DATE )A2 WHERE A1.SHIFT_DATE=A2.SHIFT_DATE(+) ) GROUP BY SHIFT_MONTH UNION ALL SELECT A1.SHIFT_DATE,A1.MOVE,NVL(A2.CRACK,0) CRACK, ROUND(100*(CASE WHEN A1.MOVE>0 THEN NVL(A2.CRACK,0)/A1.MOVE END),1) RATIO FROM ( SELECT SHIFT_DATE,SUM(MOVE) MOVE FROM A3MFGYW1.EQPG_MOVE_COUNT WHERE SHIFT_DATE>=TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') --AND LOCATION='N1A3' GROUP BY SHIFT_DATE )A1, ( SELECT SHIFT_DATE,SUM(CHILD_QTY) CRACK FROM ( SELECT SHIFT_DATE,CHILD_LOT_ID,CHILD_QTY,EQP_ID,EQPG_MOVE,EQPG_COUNT FROM A3MFGYW1.CRACK_LOT WHERE SHIFT_DATE>=TO_CHAR(SYSDATE-7.5/24-30,'YYYYMMDD') -- AND EQP_ID = 'CSD302'
AND EQP_ID=#{eqpId}
) GROUP BY SHIFT_DATE )A2 WHERE A1.SHIFT_DATE=A2.SHIFT_DATE(+) ) ORDER BY LENGTH(SHIFT_MONTH),SHIFT_MONTH

UPDATE A1_MFG.CRITICLE_N1A3_MOVE_ALARM_REASON
SET STATUS = nvl(#{STATUS,jdbcType=VARCHAR},STATUS)
,UPDATE_USER = #{UPDATE_USER,jdbcType=VARCHAR}
,UPDATE_TIME = SYSDATE
,DUE_DATE = nvl(#{DUE_DATE,jdbcType=VARCHAR},DUE_DATE)
,REASON = nvl(#{REASON,jdbcType=VARCHAR},REASON)
,ACTION = nvl(#{ACTION,jdbcType=VARCHAR},ACTION)
WHERE WEEK_SEQ = #{WEEK_SEQ,jdbcType=VARCHAR}
AND MODULE = #{MODULE,jdbcType=VARCHAR}
AND EQP_G = #{EQP_G,jdbcType=VARCHAR}
AND TO_CHAR(CREATE_TIME,'YYYY-MM-DD HH24:MI:SS') = #{CREATE_TIME,jdbcType=VARCHAR}

mapper.update:
UPDATE A1_MFG.CRITICLE_COMMENT_SUMMARY
SET KEY2 = #{TARGET,jdbcType=VARCHAR}
,UPDATE_USER = #{updateUser,jdbcType=VARCHAR},UPDATE_TIME = SYSDATE
WHERE FUNCTION_NAME = 'A3MoveSelfRatioTarget' AND KEY1 = #{EQP_G,jdbcType=VARCHAR}
